public class Geometry {
    static double circleArea(double radius) {
        return Math.PI * radius * radius;
    }

    static void greet(String name) {
        System.out.println("Hello, " + name + "!");
    }

    public static void main(String[] args) {
        greet("Ada");
        greet("Linus");
        double area = circleArea(2.0);
        System.out.printf("Area of a circle with radius 2: %.2f%n", area);
        System.out.println(circleArea(1.0) > 3);
    }
}

public class Sums {
    static int sum(int a, int b) {
        return a + b;
    }

    static double sum(double a, double b) {
        return a + b;
    }

    static int sum(int... numbers) {
        int total = 0;
        for (int n : numbers) {
            total += n;
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println(sum(2, 3));
        System.out.println(sum(2.5, 3));
        System.out.println(sum(1, 2, 3, 4));
        System.out.println(sum());
    }
}

import java.util.Arrays;

public class ByValue {
    static void change(int value) {
        value = 99;
    }

    static void fill(int[] values) {
        values[0] = 99;
    }

    static void replace(int[] values) {
        values = new int[] {7, 7, 7};
    }

    public static void main(String[] args) {
        int x = 1;
        int[] arr = {1, 2, 3};
        change(x);
        fill(arr);
        replace(arr);
        System.out.println(x);
        System.out.println(Arrays.toString(arr));
    }
}

public class Factorial {
    static long factorial(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * factorial(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(factorial(5));
        System.out.println(factorial(20));
    }
}
